    draftId: r.id,
    personId: r.person_id,
    personName: r.display_name,
    company: r.org_name ?? r.org_raw ?? null,
    kind: r.kind,
    ...r.reply_class ? { replyClass: r.reply_class } : {},
    subject: r.subject,
    sendAt: iso(r.send_at),
    sentAt: iso(r.sent_at),
    status: status3,
