  const [f2] = await db2.sql`
    select id, a, b, status, requested_by, created_at, accepted_at from orbit.friendships where id = ${friendshipId}::uuid`;
  const out = { friend: await friendView(db2, me2, f2, await targetNames(db2, me2)) };
